-- 自提门店管理入口。可重复执行，不授予角色。
BEGIN;
SET @trade_root=(SELECT menu_id FROM sys_menu WHERE parent_id=0 AND path='trade' AND menu_type='M' ORDER BY menu_id LIMIT 1);
SET @page=(SELECT menu_id FROM sys_menu WHERE parent_id=@trade_root AND path='pick-up-store' AND menu_type='C' ORDER BY menu_id LIMIT 1);
COMMIT;
